package lt.tomexas.serverselector.selector.ui;

import net.kyori.adventure.text.Component;
import net.kyori.adventure.text.format.NamedTextColor;

/**
 * Characters assigned to the selector's glyphs in nexo/glyphs/selector.yml (generated by
 * tools/build_selector_assets.py). Without Nexo the pack is missing, so plain-text fallbacks are used.
 */
public enum Glyph {
    CURSOR_ARROW("selector_cursor_arrow", '', "↖"),
    CURSOR_HAND("selector_cursor_hand", '', "☛"),
    ARROW_LEFT("selector_arrow_left", '', "◀"),
    ARROW_RIGHT("selector_arrow_right", '', "▶"),
    CARD("selector_card", '', ""),
    CARD_SELECTED("selector_card_selected", '', ""),
    PANEL("selector_panel", '', ""),
    DIM("selector_dim", '', ""),
    VIGNETTE("selector_vignette", '', ""),
    BUTTON("selector_button", '', ""),
    BUTTON_HOVER("selector_button_hover", '', ""),
    BAR_TRACK("selector_bar_track", '', ""),
    BAR_FILL("selector_bar_fill", '', ""),
    ICON_SWORD("selector_icon_sword", '', "⚔"),
    ICON_PICKAXE("selector_icon_pickaxe", '', "⛏"),
    ICON_AXE("selector_icon_axe", '', "◆"),
    ICON_BOW("selector_icon_bow", '', "➶"),
    ICON_HAMMER("selector_icon_hammer", '', "⚒"),
    ICON_WAND("selector_icon_wand", '', "✧"),
    ICON_BOMB("selector_icon_bomb", '', "✸"),
    ICON_TORCH("selector_icon_torch", '', "☀"),
    ICON_STAR("selector_icon_star", '', "★");

    private static boolean nexoAvailable;

    private final String id;
    private final char character;
    private final String fallback;

    Glyph(String id, char character, String fallback) {
        this.id = id;
        this.character = character;
        this.fallback = fallback;
    }

    public String id() {
        return id;
    }

    public char character() {
        return character;
    }

    /** The glyph as white text, so the texture is drawn untinted. */
    public Component component() {
        return Component.text(nexoAvailable ? String.valueOf(character) : fallback, NamedTextColor.WHITE);
    }

    public static void setNexoAvailable(boolean available) {
        nexoAvailable = available;
    }

    public static Glyph fromId(String id) {
        for (Glyph glyph : values()) {
            if (glyph.id.equalsIgnoreCase(id)) return glyph;
        }
        return null;
    }
}
